import{validateRelease,verifyEditorPassword,publishRelease,inferRepository}from'./release-core.mjs';
const $=id=>document.getElementById(id);let unlocked=false;
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function collect(){if(!unlocked)throw Error('请先解锁编辑器');return validateRelease(Object.fromEntries(['version','type','url','size','sha256','notes'].map(key=>[key,$(key).value])));}
function preview(){try{$('json-preview').textContent=JSON.stringify(collect(),null,2);}catch{$('json-preview').textContent='填写完整版本、HTTPS下载地址、大小和SHA256后生成清单。';}}
$('unlock').addEventListener('submit',async event=>{event.preventDefault();const password=$('password').value;$('password').value='';const button=$('unlock').querySelector('button');button.disabled=true;try{const config=await(await fetch('editor-lock.json',{cache:'no-store'})).json();if(!await verifyEditorPassword(password,config))throw Error('密码不正确');unlocked=true;$('login').hidden=true;$('editor').hidden=false;const response=await fetch('latest.json',{cache:'no-store'});const current=await response.json();for(const key of ['version','type','url','size','sha256','notes'])$(key).value=current[key]??'';const repo=inferRepository(location);for(const key of ['owner','repo','branch'])$(key).value=repo[key];$('feed-url').value=new URL('latest.json',location.href).href;preview();}catch(error){$('login-status').textContent=error.message||'解锁失败，请通过HTTPS或本地预览打开页面';}finally{button.disabled=false;}});
$('editor').addEventListener('input',preview);
$('package').addEventListener('change',async()=>{const file=$('package').files[0];if(!file)return;if(file.size>512*1024*1024){status('文件超过512MB，未处理',true);return;}status('正在本地计算安装包校验值，文件不会上传…');try{const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());$('sha256').value=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');$('size').value=file.size;$('type').value=file.name.toLowerCase().endsWith('.exe')?'exe':'zip';preview();status('校验值已填入。请确认下载地址对应这一个文件。');}catch{status('本地校验计算失败，可手动填写SHA256和文件大小',true);}finally{$('package').value='';}});
$('export').addEventListener('click',()=>{try{const release=collect();const url=URL.createObjectURL(new Blob([JSON.stringify(release,null,2)+'\n'],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='latest.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('清单已导出。请替换GitHub仓库中的 dist/latest.json 并提交。');}catch(error){status(error.message,true);}});
$('copy-json').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(JSON.stringify(collect(),null,2));status('清单已复制，可粘贴到仓库的 dist/latest.json。');}catch(error){status(error.message||'复制失败，请使用导出',true);}});
$('lock').addEventListener('click',()=>{unlocked=false;$('token').value='';$('editor').hidden=true;$('login').hidden=false;$('password').focus();});
$('publish').addEventListener('click',async()=>{const button=$('publish');button.disabled=true;try{if(!unlocked)throw Error('请先解锁编辑器');const result=await publishRelease({owner:$('owner').value.trim(),repo:$('repo').value.trim(),branch:$('branch').value.trim(),token:$('token').value,release:collect()});status('已提交版本清单。等待GitHub Pages部署完成后，程序即可检测新版本。');$('commit').replaceChildren();if(result.commitUrl?.startsWith('https://github.com/')){const link=document.createElement('a');link.textContent='查看本次提交 ↗';link.href=result.commitUrl;link.target='_blank';link.rel='noopener';$('commit').append(link);}}catch(error){status(error.message,true);}finally{$('token').value='';button.disabled=false;}});
window.addEventListener('pagehide',()=>{$('token').value='';$('password').value='';unlocked=false;});
